tool_input.command:
mkdir -p migrations/down
cat > migrations/002_orders_amount_cents.sql <<'EOF'
-- Expand step of renaming orders.total_cents -> orders.amount_cents.
-- total_cents stays until every server runs code that uses amount_cents (contract migration later).
set lock_timeout = '5s';

alter table orders add column amount_cents integer;

create function orders_sync_amount_cents() returns trigger language plpgsql as $$
begin
  if new.amount_cents is null then
    new.amount_cents := new.total_cents;
  elsif new.total_cents is null then
    new.total_cents := new.amount_cents;
  elsif tg_op = 'UPDATE' then
    if new.amount_cents is distinct from old.amount_cents then
      new.total_cents := new.amount_cents;
    else
      new.amount_cents := new.total_cents;
    end if;
  end if;
  return new;
end $$;

create trigger orders_sync_amount_cents before insert or update on orders
  for each row execute function orders_sync_amount_cents();
EOF
cat > migrations/down/002_orders_amount_cents.sql <<'EOF'
drop trigger orders_sync_amount_cents on orders;
drop function orders_sync_amount_cents();
alter table orders drop column amount_cents;
EOF
cat > db/backfill_orders_amount_cents.sql <<'EOF'
-- Run repeatedly until it updates 0 rows (batched to avoid long locks on a big table).
update orders set amount_cents = total_cents
where id in (select id from orders where amount_cents is null limit 5000);
EOF
sed -i '' 's/total_cents, created_at from orders/amount_cents, created_at from orders/' src/app.ts
sed -i '' 's/orders (user_id, status, total_cents/orders (user_id, status, amount_cents/' db/seed.sql
grep -rn "total_cents" src test db 2>/dev/null; pnpm db:reset 2>&1 | tail -5; pnpm typecheck 2>&1 | tail -3; pnpm test 2>&1 | tail -8
